// logo -- the bundled ASCII-banner start view.
//
// The FIRST bundled client plugin, exercising exactly the surface a
// third-party plugin would: one StartView registration, art generated by the
// plugin's own generator (logo_generator.{hpp,cpp}), colors from theme roles,
// config from this plugin's client-plugins.json entry.
//
// RANDOMNESS: every start (and, by default, every new session) gets a
// different banner -- a random style from the allowed pool, and a random fill
// character per glyph cell. The art is generated ONCE per session id and
// cached: Render runs at ~20 Hz, and regenerating per frame would re-randomize
// the banner faster than anyone could read it. The generator itself is
// deterministic for a seed, so the cached art is exactly reproducible.
//
// DEGRADE: a terminal narrower than the art renders a plain styled text
// fallback instead of wrapped glyphs. Every render path is also covered by
// the host's throw containment, but the plugin throws nothing by design.

#include <ftxui/dom/elements.hpp>
#include <ftxui/screen/terminal.hpp>
#include <nlohmann/json.hpp>

#include <algorithm>
#include <cstdio>
#include <map>
#include <memory>
#include <mutex>
#include <random>
#include <stdexcept>
#include <string>
#include <vector>

#include "logo_generator.hpp"
#include "minimal/client/plugins/client_plugin_abi.h"
#include "minimal/common/abi_tag.hpp"

namespace {

using minimal::client::Theme;
namespace plugins = minimal::client::plugins;
using minimal::logo::ArtWidth;
using minimal::logo::BuiltinStyles;
using minimal::logo::CanRender;
using minimal::logo::GenerateLogo;
using minimal::logo::GenerateOptions;

struct LogoConfig {
    std::string text = "minimal";
    // The title block's byline. The version half is NOT configured: it comes
    // from the binary itself (minimal::common::Version()), so the banner can
    // never disagree with what is actually running.
    std::string author = "lim8en1";
    std::vector<std::string> styles;   // empty = every built-in style
    std::string charset;               // empty = each style's own pool
    bool regenerate_per_session = true;
};

LogoConfig ParseConfig(const nlohmann::json& config) {
    LogoConfig out;
    if (!config.is_object()) return out;
    if (auto it = config.find("text"); it != config.end() && it->is_string()) {
        out.text = it->get<std::string>();
    }
    if (auto it = config.find("author"); it != config.end() && it->is_string()) {
        out.author = it->get<std::string>();
    }
    if (auto it = config.find("charset"); it != config.end() && it->is_string()) {
        out.charset = it->get<std::string>();
    }
    if (auto it = config.find("regenerate_per_session");
        it != config.end() && it->is_boolean()) {
        out.regenerate_per_session = it->get<bool>();
    }
    if (auto it = config.find("styles"); it != config.end() && it->is_array()) {
        for (const auto& entry : *it) {
            if (entry.is_string()) out.styles.push_back(entry.get<std::string>());
        }
        // Names that match nothing built in are dropped with a startup
        // warning; an empty RESULT means the pool is empty, which would make
        // every render fail -- treat that as "no restriction" instead.
        std::vector<std::string> known;
        for (const auto& style : BuiltinStyles()) known.push_back(style.name);
        std::vector<std::string> allowed;
        for (const auto& name : out.styles) {
            if (std::find(known.begin(), known.end(), name) != known.end()) {
                allowed.push_back(name);
            } else {
                std::fprintf(stderr, "minimal: plugin 'logo': unknown style '%s'\n",
                             name.c_str());
            }
        }
        out.styles = allowed;
    }
    return out;
}

class LogoStartView final : public plugins::StartView {
public:
    LogoStartView(LogoConfig config, std::uint32_t rng_seed)
        : config_(std::move(config)), rng_(rng_seed) {}

    const plugins::ViewSpec& spec() const override { return spec_; }

    ftxui::Element Render(const std::string& session_id, const Theme& theme) const override {
        const auto art = ArtFor(session_id);
        if (art.empty()) return ftxui::emptyElement();

        // Width degradation: wrapped glyph art is unreadable, so a terminal
        // too narrow for the art plus margins gets the plain title block
        // instead of wrapped glyphs.
        const auto terminal = ftxui::Terminal::Size();
        if (terminal.dimx > 0 && ArtWidth(art) > static_cast<std::size_t>(terminal.dimx) - 2) {
            return Fallback(theme);
        }

        ftxui::Elements lines;
        lines.push_back(Title(theme));
        for (const auto& line : art) {
            lines.push_back(ftxui::text(line) | ftxui::color(theme.ColorFor("banner_art")));
        }
        lines.push_back(Hint(theme));
        return ftxui::vbox(std::move(lines));
    }

private:
    const std::vector<std::string>& ArtFor(const std::string& session_id) const {
        std::lock_guard<std::mutex> lock(mtx_);
        // A random seed per key: process start for the app-level banner (the
        // empty session id), and one per session when regenerating. With
        // regenerate_per_session=false every key resolves to the shared key,
        // so one art serves every key regardless of query order.
        const std::string& cache_key =
            config_.regenerate_per_session ? session_id : kSharedKey;
        auto cached = cache_.find(cache_key);
        if (cached != cache_.end()) return cached->second;

        const auto seed = rng_();
        return cache_.emplace(cache_key, Generate(seed)).first->second;
    }

    std::vector<std::string> Generate(std::uint32_t seed) const {
        GenerateOptions options;
        options.text = config_.text;
        options.styles = config_.styles;
        options.charset = config_.charset;

        // The style pool: the config's allowed set, or every built-in style.
        const auto& builtins = BuiltinStyles();
        const std::vector<std::string>& pool =
            !config_.styles.empty() ? config_.styles : [&] {
                std::vector<std::string> names;
                for (const auto& style : builtins) names.push_back(style.name);
                return names;
            }();
        if (pool.empty()) return {};

        std::uniform_int_distribution<std::size_t> pick(0, pool.size() - 1);
        const std::string& style = pool[pick(rng_)];
        try {
            return GenerateLogo(options, style, seed);
        } catch (const std::exception&) {
            // Unrenderable text or a broken charset is a config problem, not
            // a render-time surprise: no banner, not a crash. The host's
            // containment would log per frame; this logs nothing per frame.
            return {};
        }
    }

    ftxui::Element Fallback(const Theme& theme) const {
        return ftxui::vbox({Title(theme),
                            ftxui::text(config_.text) | ftxui::bold |
                                ftxui::color(theme.ColorFor("banner_art")),
                            Hint(theme)});
    }

    // The title block above the art -- the word in caps plus the version the
    // RUNNING binary reports, never one hardcoded into the plugin.
    ftxui::Element Title(const Theme& theme) const {
        return ftxui::vbox(
            {ftxui::text("MINIMAL v" + std::string(minimal::common::Version())) | ftxui::bold |
                 ftxui::color(theme.ColorFor("banner_art")),
             ftxui::text("   by " + config_.author) | ftxui::color(theme.ColorFor("banner_hint"))});
    }

    ftxui::Element Hint(const Theme& theme) const {
        return ftxui::text("ctrl+o opens the session picker; typing starts a session") |
               ftxui::dim | ftxui::color(theme.ColorFor("banner_hint"));
    }

    plugins::ViewSpec spec_{"logo.banner", "minimal banner", plugins::ViewPlacement::Panel, ""};
    LogoConfig config_;
    mutable std::mutex mtx_;
    mutable std::map<std::string, std::vector<std::string>> cache_;
    mutable std::mt19937 rng_;  // Render is loop-thread only; the mutex covers it anyway

    static constexpr const char* kSharedKey = "";
};

}  // namespace

extern "C" {

const char* minimal_client_plugin_abi_tag() { return minimal::common::AbiTag(); }
const char* minimal_client_plugin_name() { return "logo"; }
const char* minimal_client_plugin_version() { return minimal::common::Version(); }

void minimal_client_plugin_register_start_views(
    plugins::StartViewRegistry& registry,
    const plugins::ClientPluginRegistrationContext& context) {
    auto config = ParseConfig(context.config);
    if (!CanRender(config.text)) {
        std::fprintf(stderr, "minimal: plugin 'logo': no glyph for some character of '%s' -- "
                             "not registering\n",
                     config.text.c_str());
        return;
    }
    std::random_device device;
    registry.Register(std::make_unique<LogoStartView>(std::move(config), device()));
}

}  // extern "C"
